#!/usr/bin/env bash
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
tmpdir="$(mktemp -d /tmp/mckernel-rust-equiv.XXXXXX)"
if [ "${MCKERNEL_RUST_EQUIV_KEEP_TMP:-0}" = 1 ]; then
	printf 'keeping equivalence tmpdir: %s\n' "${tmpdir}" >&2
else
	trap 'rm -rf "${tmpdir}"' EXIT
fi

cd "${repo_root}"

cat > "${tmpdir}/rbtree_equiv.c" <<'EOF_RBTREE'
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

struct rb_node {
	unsigned long __rb_parent_color;
	struct rb_node *rb_right;
	struct rb_node *rb_left;
} __attribute__((aligned(sizeof(long))));

struct rb_root {
	struct rb_node *rb_node;
};

struct rb_augment_callbacks {
	void (*propagate)(struct rb_node *node, struct rb_node *stop);
	void (*copy)(struct rb_node *old, struct rb_node *new);
	void (*rotate)(struct rb_node *old, struct rb_node *new);
};

#define rb_entry(ptr, type, member) ((type *)((char *)(ptr) - offsetof(type, member)))

extern void rb_insert_color(struct rb_node *, struct rb_root *);
extern void rb_erase(struct rb_node *, struct rb_root *);
extern struct rb_node *__rb_parent(unsigned long);
extern unsigned long __rb_color(unsigned long);
extern int __rb_is_black(unsigned long);
extern int __rb_is_red(unsigned long);
extern unsigned long rb_color(const struct rb_node *);
extern int rb_is_red(const struct rb_node *);
extern int rb_is_black(const struct rb_node *);
extern struct rb_node *rb_next(const struct rb_node *);
extern struct rb_node *rb_next_safe(const struct rb_node *);
extern struct rb_node *rb_prev(const struct rb_node *);
extern struct rb_node *rb_first(const struct rb_root *);
extern struct rb_node *rb_first_safe(const struct rb_root *);
extern struct rb_node *rb_last(const struct rb_root *);
extern struct rb_node *rb_first_postorder(const struct rb_root *);
extern struct rb_node *rb_next_postorder(const struct rb_node *);
extern void rb_replace_node(struct rb_node *, struct rb_node *, struct rb_root *);
extern struct rb_node *rb_parent(const struct rb_node *);
extern int rb_empty_root(const struct rb_root *);
extern int rb_empty_node(const struct rb_node *);
extern void rb_clear_node(struct rb_node *);
extern void rb_link_node(struct rb_node *, struct rb_node *,
			 struct rb_node **);
extern void rb_set_parent(struct rb_node *, struct rb_node *);
extern void rb_set_parent_color(struct rb_node *, struct rb_node *, int);
extern void __rb_change_child(struct rb_node *, struct rb_node *,
			      struct rb_node *, struct rb_root *);
extern void __rb_insert_augmented(struct rb_node *, struct rb_root *,
				  void (*)(struct rb_node *, struct rb_node *));
extern void rb_insert_augmented(struct rb_node *, struct rb_root *,
				const struct rb_augment_callbacks *);
extern struct rb_node *__rb_erase_augmented(struct rb_node *,
					    struct rb_root *,
					    const struct rb_augment_callbacks *);
extern void rb_erase_augmented(struct rb_node *, struct rb_root *,
			       const struct rb_augment_callbacks *);
extern struct rb_node *rb_preorder_dfs_search(const struct rb_root *,
					      _Bool (*)(struct rb_node *, void *),
					      void *);

int ihk_mc_chk_page_address(unsigned long mem_addr) { (void)mem_addr; return 0; }
__attribute__((weak)) unsigned long virt_to_phys(void *v) { return (unsigned long)v; }
__attribute__((weak)) void *phys_to_virt(unsigned long p) { return (void *)p; }
__attribute__((weak)) int zero_at_free = 1;

struct item {
	int key;
	int value;
	struct rb_node rb;
};

struct aug_item {
	int key;
	unsigned long subtree_sum;
	struct rb_node rb;
};

static void insert_item(struct rb_root *root, struct item *item)
{
	struct rb_node **link = &root->rb_node;
	struct rb_node *parent = NULL;

	while (*link) {
		struct item *entry = rb_entry(*link, struct item, rb);
		parent = *link;
		if (item->key < entry->key)
			link = &(*link)->rb_left;
		else if (item->key > entry->key)
			link = &(*link)->rb_right;
		else
			exit(2);
	}

	rb_link_node(&item->rb, parent, link);
	if (rb_parent(&item->rb) != parent ||
			item->rb.rb_left || item->rb.rb_right || *link != &item->rb)
		exit(11);
	rb_insert_color(&item->rb, root);
}

static _Bool match_key(struct rb_node *node, void *arg)
{
	return rb_entry(node, struct item, rb)->key == *(int *)arg;
}

static void require_sorted(struct rb_root *root, const int *expected, int count)
{
	struct rb_node *node = rb_first(root);
	int i = 0;

	if (node != rb_first_safe(root))
		exit(3);

	for (; node; node = rb_next(node), i++) {
		if (i >= count || rb_entry(node, struct item, rb)->key != expected[i])
			exit(4);
		if (rb_next_safe(node) != rb_next(node))
			exit(5);
	}
	if (i != count)
		exit(6);

	node = rb_last(root);
	for (i = count - 1; i >= 0; i--, node = rb_prev(node)) {
		if (!node || rb_entry(node, struct item, rb)->key != expected[i])
			exit(7);
	}
	if (node)
		exit(8);
}

static int aug_propagate_count;
static int aug_copy_count;
static int aug_rotate_count;

static unsigned long aug_compute(struct aug_item *item)
{
	unsigned long sum = (unsigned long)item->key;

	if (item->rb.rb_left)
		sum += rb_entry(item->rb.rb_left, struct aug_item, rb)->subtree_sum;
	if (item->rb.rb_right)
		sum += rb_entry(item->rb.rb_right, struct aug_item, rb)->subtree_sum;
	return sum;
}

static void aug_propagate(struct rb_node *node, struct rb_node *stop)
{
	while (node != stop) {
		struct aug_item *item = rb_entry(node, struct aug_item, rb);

		item->subtree_sum = aug_compute(item);
		aug_propagate_count++;
		node = rb_parent(node);
	}
}

static void aug_copy(struct rb_node *old, struct rb_node *new)
{
	rb_entry(new, struct aug_item, rb)->subtree_sum =
		rb_entry(old, struct aug_item, rb)->subtree_sum;
	aug_copy_count++;
}

static void aug_rotate(struct rb_node *old, struct rb_node *new)
{
	struct aug_item *old_item = rb_entry(old, struct aug_item, rb);
	struct aug_item *new_item = rb_entry(new, struct aug_item, rb);

	new_item->subtree_sum = old_item->subtree_sum;
	old_item->subtree_sum = aug_compute(old_item);
	aug_rotate_count++;
}

static const struct rb_augment_callbacks aug_callbacks = {
	aug_propagate, aug_copy, aug_rotate
};

static void insert_aug_item(struct rb_root *root, struct aug_item *item)
{
	struct rb_node **link = &root->rb_node;
	struct rb_node *parent = NULL;

	while (*link) {
		struct aug_item *entry = rb_entry(*link, struct aug_item, rb);

		parent = *link;
		if (item->key < entry->key)
			link = &(*link)->rb_left;
		else if (item->key > entry->key)
			link = &(*link)->rb_right;
		else
			exit(20);
	}

	item->subtree_sum = (unsigned long)item->key;
	rb_link_node(&item->rb, parent, link);
	aug_propagate(parent, NULL);
	rb_insert_augmented(&item->rb, root, &aug_callbacks);
}

static void require_aug_sorted(struct rb_root *root, const int *expected,
			       int count)
{
	struct rb_node *node = rb_first(root);
	unsigned long total = 0;
	int i = 0;

	for (; i < count; i++)
		total += (unsigned long)expected[i];
	if (count && rb_entry(root->rb_node, struct aug_item, rb)->subtree_sum != total)
		exit(21);

	for (i = 0; node; node = rb_next(node), i++) {
		if (i >= count ||
				rb_entry(node, struct aug_item, rb)->key != expected[i])
			exit(22);
	}
	if (i != count)
		exit(23);
}

static void require_exported_helpers(void)
{
	struct rb_root root = { NULL };
	struct rb_node parent = { 0 };
	struct rb_node child = { 0 };
	struct rb_node replacement = { 0 };

	rb_set_parent_color(&child, &parent, 0);
	if (__rb_parent(child.__rb_parent_color) != &parent ||
			__rb_color(child.__rb_parent_color) != 0 ||
			!__rb_is_red(child.__rb_parent_color) ||
			rb_parent(&child) != &parent ||
			rb_color(&child) != 0 || !rb_is_red(&child) ||
			rb_is_black(&child))
		exit(16);

	rb_set_parent_color(&child, &parent, 1);
	if (__rb_parent(child.__rb_parent_color) != &parent ||
			__rb_color(child.__rb_parent_color) != 1 ||
			!__rb_is_black(child.__rb_parent_color) ||
			rb_color(&child) != 1 || !rb_is_black(&child) ||
			rb_is_red(&child))
		exit(17);

	rb_set_parent(&child, NULL);
	if (rb_parent(&child) != NULL || rb_color(&child) != 1)
		exit(18);

	root.rb_node = &parent;
	parent.rb_left = &child;
	__rb_change_child(&child, &replacement, &parent, &root);
	if (parent.rb_left != &replacement)
		exit(19);
	__rb_change_child(&parent, &child, NULL, &root);
	if (root.rb_node != &child)
		exit(24);
}

int main(void)
{
	struct rb_root root = { NULL };
	struct rb_root aug_root = { NULL };
	int keys[] = { 40, 10, 70, 20, 60, 80, 30, 50, 15, 65, 5, 75 };
	struct item items[sizeof(keys) / sizeof(keys[0])];
	struct aug_item aug_items[sizeof(keys) / sizeof(keys[0])];
	int sorted[] = { 5, 10, 15, 20, 30, 40, 50, 60, 65, 70, 75, 80 };
	int after_erase[] = { 5, 10, 15, 20, 30, 50, 60, 65, 70, 75, 80 };
	int target = 65;
	struct item replacement = { .key = 65, .value = 6500 };
	struct rb_node *found;
	int post_count = 0;

	require_exported_helpers();
	if (!rb_empty_root(&root))
		exit(14);

	for (size_t i = 0; i < sizeof(items) / sizeof(items[0]); i++) {
		items[i].key = keys[i];
		items[i].value = keys[i] * 10;
		rb_clear_node(&items[i].rb);
		aug_items[i].key = keys[i];
		aug_items[i].subtree_sum = 0;
		rb_clear_node(&aug_items[i].rb);
		if (!rb_empty_node(&items[i].rb))
			exit(12);
		insert_item(&root, &items[i]);
		insert_aug_item(&aug_root, &aug_items[i]);
		if (rb_empty_node(&items[i].rb))
			exit(13);
		if (rb_empty_root(&root))
			exit(15);
	}

	require_sorted(&root, sorted, 12);
	require_aug_sorted(&aug_root, sorted, 12);
	found = rb_preorder_dfs_search(&root, match_key, &target);
	if (!found)
		exit(9);
	rb_replace_node(found, &replacement.rb, &root);
	require_sorted(&root, sorted, 12);

	for (found = rb_first_postorder(&root); found; found = rb_next_postorder(found))
		post_count++;
	if (post_count != 12)
		exit(10);

	for (size_t i = 0; i < sizeof(items) / sizeof(items[0]); i++) {
		if (items[i].key == 40) {
			rb_erase(&items[i].rb, &root);
			break;
		}
	}
	require_sorted(&root, after_erase, 11);
	rb_erase_augmented(&aug_items[0].rb, &aug_root, &aug_callbacks);
	require_aug_sorted(&aug_root, after_erase, 11);
	if (!aug_propagate_count || !aug_copy_count)
		exit(25);
	printf("rbtree ok count=11 first=5 last=80 post=%d aug=%d/%d/%d\n",
	       post_count, aug_propagate_count, aug_copy_count,
	       aug_rotate_count);
	return 0;
}
EOF_RBTREE

cat > "${tmpdir}/llist_equiv.c" <<'EOF_LLIST'
#include <stdio.h>
#include <stdlib.h>

struct llist_node { struct llist_node *next; };
struct llist_head { struct llist_node *first; };

extern void init_llist_head(struct llist_head *);
extern _Bool llist_empty(const struct llist_head *);
extern struct llist_node *llist_next(struct llist_node *);
extern _Bool llist_add_batch(struct llist_node *, struct llist_node *,
			     struct llist_head *);
extern _Bool llist_add(struct llist_node *, struct llist_head *);
extern struct llist_node *llist_del_all(struct llist_head *);
extern struct llist_node *llist_del_first(struct llist_head *);
extern struct llist_node *llist_reverse_order(struct llist_node *);

struct item {
	int value;
	struct llist_node node;
};

#define entry(ptr) ((struct item *)((char *)(ptr) - __builtin_offsetof(struct item, node)))

static void require(int cond)
{
	if (!cond)
		exit(2);
}

int main(void)
{
	struct llist_head head = { (struct llist_node *)0x1 };
	struct item items[6];
	struct llist_node *node;
	struct llist_node *rev;
	int sum = 0;

	init_llist_head(&head);
	require(llist_empty(&head));
	for (int i = 0; i < 6; i++) {
		items[i].value = i + 1;
		items[i].node.next = NULL;
	}

	items[0].node.next = &items[1].node;
	items[1].node.next = &items[2].node;
	require(llist_add_batch(&items[0].node, &items[2].node, &head) == 1);
	items[3].node.next = &items[4].node;
	require(llist_add_batch(&items[3].node, &items[4].node, &head) == 0);
	node = llist_del_first(&head);
	require(node == &items[3].node && head.first == &items[4].node);
	require(llist_next(node) == &items[4].node);
	node = llist_del_first(&head);
	require(node == &items[4].node);
	require(!llist_empty(&head));
	node = llist_del_all(&head);
	require(node == &items[0].node && llist_empty(&head));
	require(llist_add(&items[5].node, &head) == 1);
	require(llist_add_batch(node, &items[2].node, &head) == 0);
	rev = llist_reverse_order(llist_del_all(&head));
	for (node = rev; node; node = node->next)
		sum = sum * 10 + entry(node)->value;
	printf("llist ok sum=%d first=%d\n", sum, entry(rev)->value);
	return 0;
}
EOF_LLIST

cat > "${tmpdir}/waitq_equiv.c" <<'EOF_WAITQ'
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

struct thread;
struct waitq_entry;

typedef int (*waitq_func_t)(struct waitq_entry *, unsigned, int, void *);

typedef struct ihk_spinlock {
	union {
		unsigned int head_tail;
		struct {
			unsigned short head;
			unsigned short tail;
		} tickets;
	};
} ihk_spinlock_t;

struct list_head {
	struct list_head *next;
	struct list_head *prev;
};

typedef struct waitq {
	ihk_spinlock_t lock;
	struct list_head waitq;
} waitq_t;

typedef struct waitq_entry {
	struct list_head link;
	void *private;
	unsigned int flags;
	waitq_func_t func;
} waitq_entry_t;

struct item {
	int id;
	int wakes;
	waitq_entry_t entry;
};

struct fake_thread {
	int pad;
	int status;
};

extern void waitq_init(waitq_t *);
extern void waitq_init_entry(waitq_entry_t *, struct thread *);
extern void waitq_init_locked_entry(waitq_entry_t *, struct thread *);
extern void waitq_add_entry_locked(waitq_t *, waitq_entry_t *);
extern void waitq_remove_entry_locked(waitq_t *, waitq_entry_t *);
extern int waitq_wake_nr_locked(waitq_t *, int);
extern int waitq_wake_schedule_needed_result(int);
extern int waitq_active(waitq_t *);
extern void waitq_add_entry(waitq_t *, waitq_entry_t *);
extern void waitq_remove_entry(waitq_t *, waitq_entry_t *);
extern void waitq_wakeup(waitq_t *);
extern int waitq_wake_nr(waitq_t *, int);
extern void waitq_prepare_to_wait_result(waitq_t *, waitq_entry_t *, int,
					 void *, unsigned long);
extern void waitq_finish_wait_result(waitq_t *, waitq_entry_t *, void *,
				     unsigned long, int);

int sched_wakeup_thread(struct thread *thread, int state)
{
	return ((uintptr_t)thread ^ (unsigned int)state) & 0x7fffffff;
}

int sched_wakeup_thread_locked(struct thread *thread, int state)
{
	return (((uintptr_t)thread << 1) ^ (unsigned int)state) & 0x7fffffff;
}

static int schedule_calls;
void schedule(void)
{
	schedule_calls++;
}
void preempt_disable(void) {}
void preempt_enable(void) {}
void cpu_pause(void) {}

void ihk_mc_spinlock_init(ihk_spinlock_t *lock)
{
	lock->head_tail = 0;
}

void __ihk_mc_spinlock_lock_noirq(ihk_spinlock_t *lock)
{
	unsigned int old;
	unsigned short wait_for;

	preempt_disable();
	old = __sync_fetch_and_add(&lock->head_tail, 2U << 16);
	wait_for = (unsigned short)(old >> 16);
	while ((unsigned short)lock->head_tail != wait_for)
		cpu_pause();
}

void __ihk_mc_spinlock_unlock_noirq(ihk_spinlock_t *lock)
{
	__sync_fetch_and_add(&lock->tickets.head, 2);
	preempt_enable();
}

static void mix(unsigned long *digest, unsigned long value)
{
	*digest ^= value + 0x9e3779b97f4a7c15UL + (*digest << 6) + (*digest >> 2);
}

static void require(int condition)
{
	if (!condition)
		exit(21);
}

static struct item *item_from_entry(waitq_entry_t *entry)
{
	return (struct item *)((char *)entry - offsetof(struct item, entry));
}

static struct item *item_from_link(struct list_head *link)
{
	return item_from_entry((waitq_entry_t *)((char *)link -
		offsetof(waitq_entry_t, link)));
}

static int record_wake(waitq_entry_t *entry, unsigned mode, int flags, void *key)
{
	struct item *item = item_from_entry(entry);

	item->wakes += 1 + (int)mode + flags + (key != NULL);
	return item->id;
}

static void digest_waitq(unsigned long *digest, waitq_t *waitq)
{
	struct list_head *head = &waitq->waitq;
	struct list_head *pos = head->next;
	int count = 0;

	require(head->prev->next == head);
	require(head->next->prev == head);
	mix(digest, waitq->lock.head_tail);
	while (pos != head) {
		struct item *item = item_from_link(pos);

		require(pos->next->prev == pos);
		require(pos->prev->next == pos);
		mix(digest, ((unsigned long)(unsigned int)item->id << 32) |
			    (unsigned int)item->wakes);
		pos = pos->next;
		require(++count < 32);
	}
	mix(digest, (unsigned long)count);
}

int main(void)
{
	waitq_t waitq;
	struct item items[5];
	unsigned long digest = 0x0bad5eed7157cafeUL;
	int ret;

	for (int i = 0; i < 5; i++) {
		items[i].id = i + 10;
		items[i].wakes = 0;
		items[i].entry.flags = 0xf00d0000U + i;
		waitq_init_entry(&items[i].entry,
				 (struct thread *)(uintptr_t)(0x1000 + i * 0x40));
		require(items[i].entry.func != NULL);
		mix(&digest, (unsigned long)items[i].entry.func(
			&items[i].entry, 0, 0, NULL));
		items[i].entry.func = record_wake;
		require(items[i].entry.private ==
			(void *)(uintptr_t)(0x1000 + i * 0x40));
		require(items[i].entry.flags == 0);
	}

	items[4].entry.flags = 0xbeef0004U;
	waitq_init_locked_entry(&items[4].entry,
				(struct thread *)(uintptr_t)0x5a5a);
	require(items[4].entry.private == (void *)(uintptr_t)0x5a5a);
	require(items[4].entry.flags == 0);
	require(items[4].entry.func != NULL);
	mix(&digest, (unsigned long)items[4].entry.func(
		&items[4].entry, 0, 0, NULL));

	waitq.lock.head_tail = 0xffffffffU;
	waitq_init(&waitq);
	require(waitq.lock.head_tail == 0);
	digest_waitq(&digest, &waitq);

	waitq_add_entry_locked(&waitq, &items[0].entry);
	waitq_add_entry_locked(&waitq, &items[1].entry);
	waitq_add_entry_locked(&waitq, &items[2].entry);
	digest_waitq(&digest, &waitq);

	ret = waitq_wake_nr_locked(&waitq, 0);
	require(ret == 0);
	require(waitq_wake_schedule_needed_result(ret) == 0);
	require(items[0].wakes == 0 && items[1].wakes == 0 && items[2].wakes == 0);
	mix(&digest, (unsigned long)(int)ret);

	ret = waitq_wake_nr_locked(&waitq, 2);
	require(ret == 2);
	require(waitq_wake_schedule_needed_result(ret) == 1);
	require(items[0].wakes == 1 && items[1].wakes == 1 && items[2].wakes == 0);
	mix(&digest, (unsigned long)(int)ret);
	digest_waitq(&digest, &waitq);

	waitq_remove_entry_locked(&waitq, &items[1].entry);
	require(items[1].entry.link.next == &items[1].entry.link);
	require(items[1].entry.link.prev == &items[1].entry.link);
	digest_waitq(&digest, &waitq);

	waitq_add_entry_locked(&waitq, &items[3].entry);
	waitq_add_entry_locked(&waitq, &items[1].entry);
	digest_waitq(&digest, &waitq);

	ret = waitq_wake_nr_locked(&waitq, 10);
	require(ret == 3);
	require(items[0].wakes == 2 && items[2].wakes == 1 &&
		items[3].wakes == 1 && items[1].wakes == 2);
	mix(&digest, (unsigned long)(int)ret);
	digest_waitq(&digest, &waitq);

	waitq_remove_entry_locked(&waitq, &items[0].entry);
	waitq_remove_entry_locked(&waitq, &items[2].entry);
	waitq_remove_entry_locked(&waitq, &items[3].entry);
	waitq_remove_entry_locked(&waitq, &items[1].entry);
	digest_waitq(&digest, &waitq);

	ret = waitq_wake_nr_locked(&waitq, 1);
	require(ret == -1);
	require(waitq_wake_schedule_needed_result(ret) == 0);
	mix(&digest, (unsigned long)(int)ret);

	for (int i = 0; i < 5; i++) {
		items[i].wakes = 0;
		waitq_init_entry(&items[i].entry,
				 (struct thread *)(uintptr_t)(0x3000 + i * 0x20));
		items[i].entry.func = record_wake;
	}
	waitq_init(&waitq);
	require(waitq_active(&waitq) == 0);
	waitq_add_entry(&waitq, &items[0].entry);
	waitq_add_entry(&waitq, &items[1].entry);
	require(waitq_active(&waitq) == 1);
	waitq_wakeup(&waitq);
	require(items[0].wakes == 1 && items[1].wakes == 1);
	schedule_calls = 0;
	ret = waitq_wake_nr(&waitq, 1);
	require(ret == 1);
	require(schedule_calls == 1);
	require(items[0].wakes == 2 && items[1].wakes == 1);
	waitq_remove_entry(&waitq, &items[0].entry);
	waitq_remove_entry(&waitq, &items[1].entry);
	require(waitq_active(&waitq) == 0);
	digest_waitq(&digest, &waitq);
	mix(&digest, (unsigned long)schedule_calls);

	{
		struct fake_thread current = { .pad = 0x55, .status = 0x66 };

		waitq_init(&waitq);
		waitq_init_entry(&items[4].entry,
				 (struct thread *)(uintptr_t)0x4444);
		items[4].entry.func = record_wake;
		waitq_prepare_to_wait_result(&waitq, &items[4].entry, 0x77,
			&current, offsetof(struct fake_thread, status));
		require(current.status == 0x77);
		require(waitq_active(&waitq) == 1);
		waitq_prepare_to_wait_result(&waitq, &items[4].entry, 0x88,
			&current, offsetof(struct fake_thread, status));
		require(current.status == 0x88);
		ret = waitq_wake_nr(&waitq, 10);
		require(ret == 0);
		require(items[4].wakes == 1);
		waitq_finish_wait_result(&waitq, &items[4].entry, &current,
			offsetof(struct fake_thread, status), 0x99);
		require(current.status == 0x99);
		require(waitq_active(&waitq) == 0);
		require(items[4].entry.link.next == &items[4].entry.link);
		require(items[4].entry.link.prev == &items[4].entry.link);
		digest_waitq(&digest, &waitq);
		mix(&digest, (unsigned long)(unsigned int)current.status);
	}

	printf("waitq ok digest=%016lx\n", digest);
	return 0;
}
EOF_WAITQ

cat > "${tmpdir}/list_helpers_equiv.c" <<'EOF_LIST_HELPERS'
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

struct list_head {
	struct list_head *next;
	struct list_head *prev;
};

extern void INIT_LIST_HEAD(struct list_head *list);
extern void list_add(struct list_head *new, struct list_head *head);
extern void list_add_tail(struct list_head *new, struct list_head *head);
extern void list_del(struct list_head *entry);
extern void list_del_init(struct list_head *entry);
extern void list_move(struct list_head *list, struct list_head *head);
extern void list_move_tail(struct list_head *list, struct list_head *head);
extern int list_empty(const struct list_head *head);
extern int list_empty_careful(const struct list_head *head);
extern int list_is_last(const struct list_head *list,
			const struct list_head *head);
extern int list_is_singular(const struct list_head *head);
extern void list_replace_init(struct list_head *old, struct list_head *new);
extern void list_cut_position(struct list_head *list, struct list_head *head,
			      struct list_head *entry);
extern void list_splice_init(struct list_head *list, struct list_head *head);
extern void list_splice_tail_init(struct list_head *list,
				  struct list_head *head);

#ifdef USE_C_LIST_MODEL
void INIT_LIST_HEAD(struct list_head *list)
{
	list->next = list;
	list->prev = list;
}

static void __list_add(struct list_head *new, struct list_head *prev,
		       struct list_head *next)
{
	next->prev = new;
	new->next = next;
	new->prev = prev;
	prev->next = new;
}

void list_add(struct list_head *new, struct list_head *head)
{
	__list_add(new, head, head->next);
}

void list_add_tail(struct list_head *new, struct list_head *head)
{
	__list_add(new, head->prev, head);
}

static void __list_del(struct list_head *prev, struct list_head *next)
{
	next->prev = prev;
	prev->next = next;
}

static void __list_del_entry(struct list_head *entry)
{
	__list_del(entry->prev, entry->next);
}

void list_del(struct list_head *entry)
{
	__list_del_entry(entry);
	entry->next = (void *)0x00100129;
	entry->prev = (void *)0x00200229;
}

static void list_replace(struct list_head *old, struct list_head *new)
{
	new->next = old->next;
	new->next->prev = new;
	new->prev = old->prev;
	new->prev->next = new;
}

void list_replace_init(struct list_head *old, struct list_head *new)
{
	list_replace(old, new);
	INIT_LIST_HEAD(old);
}

void list_del_init(struct list_head *entry)
{
	__list_del_entry(entry);
	INIT_LIST_HEAD(entry);
}

void list_move(struct list_head *list, struct list_head *head)
{
	__list_del_entry(list);
	list_add(list, head);
}

void list_move_tail(struct list_head *list, struct list_head *head)
{
	__list_del_entry(list);
	list_add_tail(list, head);
}

int list_empty(const struct list_head *head)
{
	return head->next == head;
}

int list_empty_careful(const struct list_head *head)
{
	struct list_head *next = head->next;
	return next == head && next == head->prev;
}

int list_is_last(const struct list_head *list, const struct list_head *head)
{
	return list->next == head;
}

int list_is_singular(const struct list_head *head)
{
	return !list_empty(head) && head->next == head->prev;
}

static void __list_cut_position(struct list_head *list, struct list_head *head,
				struct list_head *entry)
{
	struct list_head *new_first = entry->next;
	list->next = head->next;
	list->next->prev = list;
	list->prev = entry;
	entry->next = list;
	head->next = new_first;
	new_first->prev = head;
}

void list_cut_position(struct list_head *list, struct list_head *head,
		       struct list_head *entry)
{
	if (list_empty(head))
		return;
	if (list_is_singular(head) &&
	    (head->next != entry && head != entry))
		return;
	if (entry == head)
		INIT_LIST_HEAD(list);
	else
		__list_cut_position(list, head, entry);
}

static void __list_splice(const struct list_head *list,
			  struct list_head *prev, struct list_head *next)
{
	struct list_head *first = list->next;
	struct list_head *last = list->prev;

	first->prev = prev;
	prev->next = first;
	last->next = next;
	next->prev = last;
}

void list_splice_init(struct list_head *list, struct list_head *head)
{
	if (!list_empty(list)) {
		__list_splice(list, head, head->next);
		INIT_LIST_HEAD(list);
	}
}

void list_splice_tail_init(struct list_head *list, struct list_head *head)
{
	if (!list_empty(list)) {
		__list_splice(list, head->prev, head);
		INIT_LIST_HEAD(list);
	}
}
#endif

struct item {
	int value;
	struct list_head list;
};

static void require(int cond)
{
	if (!cond)
		exit(2);
}

static struct item *entry(struct list_head *list)
{
	return (struct item *)((char *)list - offsetof(struct item, list));
}

static int digest_list(struct list_head *head)
{
	struct list_head *pos;
	int digest = 0;

	for (pos = head->next; pos != head; pos = pos->next)
		digest = digest * 10 + entry(pos)->value;
	return digest;
}

int main(void)
{
	struct list_head head;
	struct list_head cut;
	struct list_head extra;
	struct item items[8];
	struct item replacement = { .value = 9 };

	INIT_LIST_HEAD(&head);
	INIT_LIST_HEAD(&cut);
	INIT_LIST_HEAD(&extra);
	for (int i = 0; i < 8; i++) {
		items[i].value = i + 1;
		INIT_LIST_HEAD(&items[i].list);
	}
	INIT_LIST_HEAD(&replacement.list);

	require(list_empty(&head));
	require(list_empty_careful(&head));
	list_add(&items[0].list, &head);
	list_add_tail(&items[1].list, &head);
	list_add(&items[2].list, &head);
	require(digest_list(&head) == 312);
	require(list_is_last(&items[1].list, &head));

	list_move_tail(&items[2].list, &head);
	require(digest_list(&head) == 123);
	list_move(&items[1].list, &head);
	require(digest_list(&head) == 213);

	list_replace_init(&items[0].list, &replacement.list);
	require(digest_list(&head) == 293);
	require(list_empty(&items[0].list));

	list_cut_position(&cut, &head, &replacement.list);
	require(digest_list(&cut) == 29);
	require(digest_list(&head) == 3);

	list_add_tail(&items[3].list, &extra);
	list_add_tail(&items[4].list, &extra);
	list_splice_init(&extra, &head);
	require(digest_list(&head) == 453);
	require(list_empty(&extra));

	list_add_tail(&items[5].list, &extra);
	list_add_tail(&items[6].list, &extra);
	list_splice_tail_init(&extra, &head);
	require(digest_list(&head) == 45367);
	require(list_empty_careful(&extra));

	list_add_tail(&items[7].list, &extra);
	require(list_is_singular(&extra));
	list_del_init(&items[7].list);
	require(list_empty(&extra));
	list_del_init(&items[6].list);
	require(digest_list(&head) == 4536);
	list_del(&items[5].list);
	require(digest_list(&head) == 453);

	printf("list_helpers ok digest=%d cut=%d\n",
	       digest_list(&head), digest_list(&cut));
	return 0;
}
EOF_LIST_HELPERS

cat > "${tmpdir}/atomic_helpers_equiv.c" <<'EOF_ATOMIC_HELPERS'
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

struct ihk_atomic { int counter; };
struct ihk_atomic64 { long counter64; };

extern int ihk_atomic_read(const struct ihk_atomic *v);
extern void ihk_atomic_set(struct ihk_atomic *v, int i);
extern void ihk_atomic_add(int i, struct ihk_atomic *v);
extern void ihk_atomic_sub(int i, struct ihk_atomic *v);
extern void ihk_atomic_inc(struct ihk_atomic *v);
extern void ihk_atomic_dec(struct ihk_atomic *v);
extern int ihk_atomic_dec_and_test(struct ihk_atomic *v);
extern int ihk_atomic_inc_and_test(struct ihk_atomic *v);
extern int ihk_atomic_add_return(int i, struct ihk_atomic *v);
extern int ihk_atomic_sub_return(int i, struct ihk_atomic *v);
extern int ihk_atomic_inc_return(struct ihk_atomic *v);
extern int ihk_atomic_dec_return(struct ihk_atomic *v);
extern long ihk_atomic64_read(const struct ihk_atomic64 *v);
extern void ihk_atomic64_set(struct ihk_atomic64 *v, long i);
extern void ihk_atomic64_inc(struct ihk_atomic64 *v);
extern long ihk_atomic64_add_return(long i, struct ihk_atomic64 *v);
extern long ihk_atomic64_sub_return(long i, struct ihk_atomic64 *v);
extern unsigned long xchg8(unsigned long *ptr, unsigned long x);
extern int xchg4(int *ptr, int x);
extern unsigned long atomic_xchg_ulong(unsigned long *ptr, unsigned long x);
extern void *atomic_xchg_ptr(void **ptr, void *x);
extern unsigned long atomic_cmpxchg8(unsigned long *addr,
				     unsigned long oldval,
				     unsigned long newval);
extern unsigned long atomic_cmpxchg4(unsigned int *addr,
				     unsigned int oldval,
				     unsigned int newval);
extern int atomic_cmpxchg_int(int *addr, int oldval, int newval);
extern unsigned long atomic_cmpxchg_ulong(unsigned long *addr,
					  unsigned long oldval,
					  unsigned long newval);
extern void *atomic_cmpxchg_ptr(void **addr, void *oldval, void *newval);
extern int compare_and_swap(void *addr, unsigned long olddata,
			    unsigned long newdata);
extern void ihk_atomic_add_long(long i, long *v);
extern void ihk_atomic_add_ulong(long i, unsigned long *v);
extern unsigned long ihk_atomic_add_long_return(long i, long *v);

#ifdef USE_C_ATOMIC_MODEL
int ihk_atomic_read(const struct ihk_atomic *v) { return v->counter; }
void ihk_atomic_set(struct ihk_atomic *v, int i) { v->counter = i; }
void ihk_atomic_add(int i, struct ihk_atomic *v) { __sync_add_and_fetch(&v->counter, i); }
void ihk_atomic_sub(int i, struct ihk_atomic *v) { __sync_sub_and_fetch(&v->counter, i); }
void ihk_atomic_inc(struct ihk_atomic *v) { __sync_add_and_fetch(&v->counter, 1); }
void ihk_atomic_dec(struct ihk_atomic *v) { __sync_sub_and_fetch(&v->counter, 1); }
int ihk_atomic_dec_and_test(struct ihk_atomic *v) { return __sync_sub_and_fetch(&v->counter, 1) == 0; }
int ihk_atomic_inc_and_test(struct ihk_atomic *v) { return __sync_add_and_fetch(&v->counter, 1) == 0; }
int ihk_atomic_add_return(int i, struct ihk_atomic *v) { return __sync_add_and_fetch(&v->counter, i); }
int ihk_atomic_sub_return(int i, struct ihk_atomic *v) { return __sync_sub_and_fetch(&v->counter, i); }
int ihk_atomic_inc_return(struct ihk_atomic *v) { return ihk_atomic_add_return(1, v); }
int ihk_atomic_dec_return(struct ihk_atomic *v) { return ihk_atomic_sub_return(1, v); }
long ihk_atomic64_read(const struct ihk_atomic64 *v) { return v->counter64; }
void ihk_atomic64_set(struct ihk_atomic64 *v, long i) { v->counter64 = i; }
void ihk_atomic64_inc(struct ihk_atomic64 *v) { __sync_add_and_fetch(&v->counter64, 1); }
long ihk_atomic64_add_return(long i, struct ihk_atomic64 *v) { return __sync_add_and_fetch(&v->counter64, i); }
long ihk_atomic64_sub_return(long i, struct ihk_atomic64 *v) { return __sync_sub_and_fetch(&v->counter64, i); }
unsigned long xchg8(unsigned long *ptr, unsigned long x) { return __sync_lock_test_and_set(ptr, x); }
int xchg4(int *ptr, int x) { return __sync_lock_test_and_set(ptr, x); }
unsigned long atomic_xchg_ulong(unsigned long *ptr, unsigned long x) { return __sync_lock_test_and_set(ptr, x); }
void *atomic_xchg_ptr(void **ptr, void *x) { return __sync_lock_test_and_set(ptr, x); }
unsigned long atomic_cmpxchg8(unsigned long *addr, unsigned long oldval, unsigned long newval) { return __sync_val_compare_and_swap(addr, oldval, newval); }
unsigned long atomic_cmpxchg4(unsigned int *addr, unsigned int oldval, unsigned int newval) { return __sync_val_compare_and_swap(addr, oldval, newval); }
int atomic_cmpxchg_int(int *addr, int oldval, int newval) { return __sync_val_compare_and_swap(addr, oldval, newval); }
unsigned long atomic_cmpxchg_ulong(unsigned long *addr, unsigned long oldval, unsigned long newval) { return __sync_val_compare_and_swap(addr, oldval, newval); }
void *atomic_cmpxchg_ptr(void **addr, void *oldval, void *newval) { return __sync_val_compare_and_swap(addr, oldval, newval); }
int compare_and_swap(void *addr, unsigned long olddata, unsigned long newdata) { return __sync_bool_compare_and_swap((unsigned long *)addr, olddata, newdata); }
void ihk_atomic_add_long(long i, long *v) { __sync_add_and_fetch(v, i); }
void ihk_atomic_add_ulong(long i, unsigned long *v) { __sync_add_and_fetch(v, i); }
unsigned long ihk_atomic_add_long_return(long i, long *v) { return __sync_add_and_fetch(v, i); }
#endif

static void require(int cond)
{
	if (!cond)
		exit(2);
}

static void mix(unsigned long *digest, unsigned long value)
{
	*digest ^= value + 0x9e3779b97f4a7c15UL + (*digest << 6) + (*digest >> 2);
}

int main(void)
{
	struct ihk_atomic a = { .counter = 0 };
	struct ihk_atomic64 a64 = { .counter64 = 0 };
	unsigned long u64 = 0x1111111122222222UL;
	unsigned int u32 = 0x12345678U;
	unsigned long cas_word = 0x0102030405060708UL;
	int x4 = 77;
	unsigned long xul = 0x1212121234343434UL;
	void *slots[3] = { &a, &a64, &cas_word };
	long sl = 10;
	unsigned long ul = 20;
	unsigned long digest = 0x61746f6d6963UL;

	ihk_atomic_set(&a, -1);
	require(ihk_atomic_read(&a) == -1);
	require(ihk_atomic_inc_and_test(&a) == 1);
	ihk_atomic_add(5, &a);
	require(ihk_atomic_add_return(7, &a) == 12);
	require(ihk_atomic_inc_return(&a) == 13);
	ihk_atomic_sub(2, &a);
	require(ihk_atomic_sub_return(9, &a) == 2);
	require(ihk_atomic_dec_return(&a) == 1);
	ihk_atomic_dec(&a);
	require(ihk_atomic_dec_and_test(&a) == 0);
	mix(&digest, (unsigned int)ihk_atomic_read(&a));

	ihk_atomic64_set(&a64, -5);
	require(ihk_atomic64_read(&a64) == -5);
	ihk_atomic64_inc(&a64);
	require(ihk_atomic64_add_return(100, &a64) == 96);
	require(ihk_atomic64_sub_return(6, &a64) == 90);
	mix(&digest, (unsigned long)ihk_atomic64_read(&a64));

	require(xchg8(&u64, 0x3333333344444444UL) == 0x1111111122222222UL);
	require(xchg4(&x4, -12) == 77);
	require(x4 == -12);
	require(atomic_xchg_ulong(&xul, 0xf0f0f0f00f0f0f0fUL) ==
		0x1212121234343434UL);
	require(xul == 0xf0f0f0f00f0f0f0fUL);
	require(atomic_xchg_ptr(&slots[0], slots[2]) == &a);
	require(slots[0] == &cas_word);
	require(atomic_cmpxchg8(&u64, 0, 1) == 0x3333333344444444UL);
	require(atomic_cmpxchg8(&u64, 0x3333333344444444UL, 0x55) ==
		0x3333333344444444UL);
	require(u64 == 0x55);
	require(atomic_cmpxchg4(&u32, 0, 1) == 0x12345678U);
	require(atomic_cmpxchg4(&u32, 0x12345678U, 0xabcdef01U) ==
		0x12345678U);
	require(u32 == 0xabcdef01U);
	require(atomic_cmpxchg_int(&x4, 0, 99) == -12);
	require(atomic_cmpxchg_int(&x4, -12, 99) == -12);
	require(x4 == 99);
	require(atomic_cmpxchg_ulong(&xul, 0, 1) == 0xf0f0f0f00f0f0f0fUL);
	require(atomic_cmpxchg_ulong(&xul, 0xf0f0f0f00f0f0f0fUL,
				     0x0101010102020202UL) ==
		0xf0f0f0f00f0f0f0fUL);
	require(xul == 0x0101010102020202UL);
	require(atomic_cmpxchg_ptr(&slots[0], slots[1], NULL) == &cas_word);
	require(atomic_cmpxchg_ptr(&slots[0], slots[2], slots[1]) ==
		&cas_word);
	require(slots[0] == &a64);
	require(compare_and_swap(&cas_word, 0, 0xaabbccddeeff0011UL) == 0);
	require(cas_word == 0x0102030405060708UL);
	require(compare_and_swap(&cas_word, 0x0102030405060708UL,
				 0xaabbccddeeff0011UL) == 1);
	require(cas_word == 0xaabbccddeeff0011UL);
	ihk_atomic_add_long(-3, &sl);
	ihk_atomic_add_ulong(4, &ul);
	require(ihk_atomic_add_long_return(9, &sl) == 16);
	require(ul == 24);
	mix(&digest, u64);
	mix(&digest, u32);
	mix(&digest, cas_word);
	mix(&digest, (unsigned int)x4);
	mix(&digest, xul);
	mix(&digest, slots[0] == &a64);
	mix(&digest, (unsigned long)sl);
	mix(&digest, ul);

	printf("atomic_helpers ok digest=%016lx a=%d a64=%ld\n",
	       digest, ihk_atomic_read(&a), ihk_atomic64_read(&a64));
	return 0;
}
EOF_ATOMIC_HELPERS

cat > "${tmpdir}/pte_helpers_equiv.c" <<'EOF_PTE_HELPERS'
