		}

		fake_mprotect_reset(NULL, 0);
		rc = mprotect_body_result(&fake_vm, &fake_lock, 0x10001UL,
			PAGE_SIZE, PROT_READ, 0x10000UL, 0x20000UL, 0, 0,
