			argv, envp, 0x4000, filename[0], fake_execveat);
		require(rc == -22);
		mix_signed(digest, rc);

		rc = execve_body_result(&ctx_byte, filename, argv, envp, NULL);
		require(rc == -14);
		mix_signed(digest, rc);
	}

	for (unsigned int f = 0; f < sizeof(futex_flags) / sizeof(futex_flags[0]); f++) {
