static void fake_xpmem_list_init(struct fake_xpmem_list *list)
{
	list->next = list;
	list->prev = list;
}

static void fake_xpmem_list_add_tail(struct fake_xpmem_list *entry,
				     struct fake_xpmem_list *head)
{
	entry->next = head;
	entry->prev = head->prev;
	head->prev->next = entry;
	head->prev = entry;
}

