		fake_xpmem_update_page_table_reset(&vm, &asp, &range,
			&tg, &tg2, &seg, &ap, &att, &pte1);
		att.flags = XPMEM_FLAG_DESTROYING;
		ret = XPMEM_UPDATE_PAGE_TABLE_CALL(&vm, &range, tg.tgid, 1);
