		fake_huge_set_ops, fake_huge_set_refcnt,
		fake_huge_set_path, fake_huge_copy_path,
		fake_huge_list_add, fake_huge_pre_log,
		fake_huge_alloc_error));
	require(fake_huge_alloc_calls == 1);
