#define ARENA_BASE 0x1000000UL
#define ARENA_SIZE (128UL * 4096UL)
#define LOCAL_PAGE_SIZE 4096UL

#define rb_entry(ptr, type, member) \
	((type *)((char *)(ptr) - __builtin_offsetof(type, member)))

