			fake_finish_send, fake_finish_log) == 0);
		require(finish_send_count == 0);
		require(finish_log_count == 0);
		mix(&digest, finish_log_digest);

		reset_finish_trace(0);
		require(ihk_numa_free_pages_finish_result(1, 0, -22,
