	int main(void)
	{
	struct rb_root root = { NULL };
	unsigned long digest = 0;
	unsigned long a, b, c;

#ifndef PAGE_ALLOC_USE_C
	linux_page_offset_base = (unsigned long)arena - ARENA_BASE;
#endif
	memset(arena, 0xa5, sizeof(arena));

