		    !req.va || req.len == 0)
			return -EINVAL;
		if (req.stag >= 0 && steering_enabled_fn(ucq, req.stag))
			return -EBUSY;

		vm = current_vm_fn();
		if (!vm)
			return -EINVAL;

		readonly = (req.flags & 1) != 0;
		va = (unsigned long)req.va;

