				}
			}
			if (pgszbits >= sizeof(unsigned long) * 8) {
				vm_read_unlock_fn(vm);
				return -EINVAL;
			}
			pgsz = 1UL << pgszbits;
			start = tofu_model_align_down(va, pgsz);
			end = tofu_model_align_up(va + req.len, pgsz);

			cq_lock_fn(ucq);
			if (req.stag < 0) {
