				req.stag = stag;
				req.offset = va - get_mbpt_start_fn(ucq, stag);
			}
			else {
				unsigned long plus_mbva;

				if (steering_enabled_fn(ucq, req.stag)) {
					cq_unlock_fn(ucq);
					vm_read_unlock_fn(vm);
