		track_unlock_addrs[i] = 0;
		track_unlock_flags[i] = 0;
	}
	for (i = 0; i < 16; i++) {
		track_noirq_lock_addrs[i] = 0;
		track_noirq_unlock_addrs[i] = 0;
	}
	for (i = 0; i < 32; i++) {
		track_log_events[i] = 0;
		track_log_ptrs[i] = NULL;
		leak_log_events[i] = 0;
		leak_log_ptrs[i] = NULL;
