static int fake_page_size(size_t current, size_t *nextp)
{
	page_size_call_count++;
	if (page_size_fail_after >= 0 &&
	    page_size_call_count > page_size_fail_after)
		return -5;
	if (current == (size_t)-1) {
		*nextp = 0x200000;
		return 0;
	}
	if (current == 0x200000) {
		*nextp = 0x1000;
		return 0;
	}
	return -5;
}

