int main(void)
{
	unsigned long digest = 0x50524f4348454c50UL;
	unsigned long clr = 0, set = 0;
	struct fake_tid tids[3] = {
		{ 10, (void *)0x1000 },
		{ 11, (void *)0x2000 },
