	fd_arg = va_arg(ap, int);
	dirp_arg = va_arg(ap, void *);
	count_arg = va_arg(ap, unsigned long);
	va_end(ap);

	if (number != 1 && number != 217) {
		errno = ENOSYS;
		return -1;
	}

	if (fd_arg == fake_getdents_passthrough_fd) {
		fake_getdents_passthrough_calls++;
