		return (long)len;
	}
	if (fd_arg == fake_overlay_getdents_linux_fd) {
		fake_getdents_linux_calls++;
		if (fake_getdents_linux_calls > 1)
			return 0;
		len = fake_getdents_linux_src_size;
		if (len > count_arg)
			len = count_arg;
		memcpy(dirp_arg, fake_getdents_linux_src, len);
