	require(strstr(buf, "BACKING FILE") != NULL);
	require(mck_crash_mcvtop_header_result(buf, sizeof(buf)) > 0);
	require(strstr(buf, "VIRT") != NULL && strstr(buf, "FLAGS") != NULL);

