	    !arch_symbols_init_fn || !spin_lock_init_fn ||
	    !register_device_fn)
		return -EINVAL;

	if (log_fn)
		log_fn(0);

	ret = symbols_init_fn();
	if (ret)
		return ret;

	ret = arch_symbols_init_fn();
	if (ret)
		return ret;

	spin_lock_init_fn(builtin_data + lock_offset);

	ihkd = register_device_fn(reg_data);
	if (!ihkd) {
		if (log_fn)
			log_fn(1);
		return -ENOMEM;
	}

	*(unsigned long *)(builtin_data + ihk_dev_offset) = ihkd;
