int ihk_smp_collect_topology_body_result(
	int (*next_cpu_fn)(int),
	int (*collect_cpu_fn)(int),
	int (*next_node_fn)(int),
	int (*collect_node_fn)(int),
	void (*log_fn)(int, int))
