{
	if (!os || !offsets)
		return -EINVAL;
	smp_lock_status_model(os, offsets->os_lock, offsets->os_status,
			      BUILTIN_OS_STATUS_HUNGUP, lock_fn, unlock_fn);
	return 0;
}

