	pat = (6UL << 0) | (1UL << 8) | (7UL << 16) | (0UL << 24) |
	      (6UL << 32) | (1UL << 40) | (7UL << 48) | (0UL << 56);
	if (!*boot_pat_state)
		*boot_pat_state = read_msr_fn(cr_pat_msr);
	write_msr_fn(cr_pat_msr, pat);
	if (log_fn)
		log_fn(2);
	return 0;
}

